{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Ingress rules lack descriptions",
      "resource": "aws_security_group.vault",
      "severity": "MEDIUM",
      "explanation": "The dynamically generated ingress rules have no descriptions, reducing auditability and making it harder to determine the purpose of each permitted port."
    },
    {
      "check_id": "CKV_AWS_277",
      "title": "Vault ingress is exposed to the public internet",
      "resource": "aws_security_group.vault",
      "severity": "HIGH",
      "explanation": "Every port in var.ingress_ports is permitted from 0.0.0.0/0, potentially exposing Vault services to any internet host. Access can be restricted to the existing VPC CIDR."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"vault\" {\n  name        = \"vault\"\n  description = \"Ingress for Vault\"\n  vpc_id      = aws_vpc.my_vpc.id\n\n  dynamic \"ingress\" {\n    iterator = port\n    for_each = var.ingress_ports\n    content {\n      description = \"Vault TCP ingress from within the VPC\"\n      from_port   = port.value\n      to_port     = port.value\n      protocol    = \"tcp\"\n      cidr_blocks = [aws_vpc.my_vpc.cidr_block]\n    }\n  }\n}\n",
  "fix_summary": "Added a description to each generated ingress rule and restricted access from the entire internet to the existing VPC CIDR. The unattached-security-group candidate was not treated as a vulnerability because this file contains no target resource to which it could be attached."
}
